-- 383: Original BrillaPrep flashcards, batch flashcards-beta-001, part 3 of 5.
-- Curriculum-aligned revision content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_09', 'deck_sys_topic_atomic', 'What is the energy of an electron in level n of a hydrogen atom (Bohr model)?', 'E = −13.6/n² eV. The negative sign means the electron is bound to the nucleus; E approaches 0 as n → ∞, which corresponds to ionisation.', NULL, NULL, 4);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_10', 'deck_sys_topic_atomic', 'State the de Broglie wavelength relation.', 'λ = h/mv = h/p: every moving particle has an associated wavelength, where h is Planck’s constant and p = mv is its momentum.', NULL, NULL, 4);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_01', 'deck_sys_topic_stoichiometry', 'Write the formula relating moles, mass and molar mass.', 'n = m/M: moles = mass in grams divided by molar mass in g/mol.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_02', 'deck_sys_topic_stoichiometry', 'Define one mole of a substance.', 'The amount of substance that contains as many particles (atoms, molecules or ions) as there are atoms in exactly 12 g of carbon-12 — that is, Avogadro’s number, 6.02 × 10²³ particles.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_03', 'deck_sys_topic_stoichiometry', 'Write the formula for concentration (molarity).', 'Concentration C = n/V in mol/dm³ (mol/L), where n is the moles of solute and V is the volume of solution in dm³.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_04', 'deck_sys_topic_stoichiometry', 'State the ideal gas equation and the meaning of each symbol.', 'PV = nRT, where P is pressure, V is volume, n is moles of gas, R is the gas constant (8.314 J·K⁻¹·mol⁻¹) and T is absolute temperature in kelvin.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_05', 'deck_sys_topic_stoichiometry', 'What is the percentage yield formula?', '% yield = (actual yield ÷ theoretical yield) × 100%.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_06', 'deck_sys_topic_stoichiometry', 'What is a limiting reagent?', 'The reactant that is completely used up first in a reaction; it determines the maximum amount of product that can form.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_07', 'deck_sys_topic_stoichiometry', 'Why must a chemical equation be balanced before stoichiometric calculations?', 'Balancing conserves atoms (mass), and the coefficients give the mole ratios in which species react and form — every mole calculation depends on those ratios.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_08', 'deck_sys_topic_stoichiometry', 'How many moles are there in 8 g of methane, CH₄? (C = 12, H = 1)', 'M(CH₄) = 12 + 4(1) = 16 g/mol, so n = 8/16 = 0.5 mol.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_09', 'deck_sys_topic_stoichiometry', 'What volume does one mole of any gas occupy at s.t.p.?', '22.4 dm³ (22.4 L) at standard temperature and pressure (0 °C and 1 atm).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_stoichiometry_10', 'deck_sys_topic_stoichiometry', 'In N₂ + 3H₂ → 2NH₃, how many moles of NH₃ form from 6 mol of H₂ with N₂ in excess?', '4 mol NH₃: the mole ratio H₂ : NH₃ is 3 : 2, so 6 × (2/3) = 4.', NULL, 'Use the coefficient ratio.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_01', 'deck_sys_topic_cells', 'State the cell theory.', 'All living organisms are composed of one or more cells; the cell is the basic structural and functional unit of life; all cells arise from pre-existing cells.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_02', 'deck_sys_topic_cells', 'Name three structural differences between prokaryotic and eukaryotic cells.', 'Prokaryotes have no membrane-bound nucleus (DNA lies free in a nucleoid region), no membrane-bound organelles, and are generally smaller; eukaryotes have a true nucleus and organelles such as mitochondria.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_03', 'deck_sys_topic_cells', 'What is the function of the nucleus?', 'It stores the cell’s genetic material (DNA) and controls the cell’s activities, including growth and reproduction.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_04', 'deck_sys_topic_cells', 'What is the function of mitochondria?', 'They carry out aerobic respiration, releasing energy from glucose and producing ATP, the cell’s usable energy currency.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_05', 'deck_sys_topic_cells', 'Which organelle is the site of photosynthesis in plant cells?', 'The chloroplast, which contains the green pigment chlorophyll that traps light energy.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_06', 'deck_sys_topic_cells', 'State three features found in plant cells but absent from animal cells.', 'A cellulose cell wall, chloroplasts, and a large permanent central vacuole.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_07', 'deck_sys_topic_cells', 'What is the function of the cell (plasma) membrane?', 'It is selectively (partially) permeable: it controls which substances enter and leave the cell.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_08', 'deck_sys_topic_cells', 'What is the role of ribosomes?', 'They are the sites of protein synthesis, translating messenger RNA into polypeptide chains.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_09', 'deck_sys_topic_cells', 'Distinguish between rough and smooth endoplasmic reticulum.', 'Rough ER is studded with ribosomes and processes newly made proteins; smooth ER lacks ribosomes and is involved in lipid synthesis and detoxification.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_cells_10', 'deck_sys_topic_cells', 'What is the function of the Golgi apparatus?', 'It modifies, sorts and packages proteins and lipids received from the endoplasmic reticulum into vesicles for secretion or delivery within the cell.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_01', 'deck_sys_topic_genetics', 'Define a gene.', 'A section of DNA that codes for a particular protein (polypeptide) and so influences a specific heritable characteristic.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_02', 'deck_sys_topic_genetics', 'What is an allele?', 'One of the alternative forms of a gene, found at the same locus (position) on homologous chromosomes — for example, the alleles for tallness and dwarfness in pea plants.', NULL, NULL, 2);
